use serde_json::Value;

/// Recursively deep-merges `overlay` into `base`.
///
/// - When both values are objects, their keys are merged recursively.
/// - When both values are arrays, `overlay` replaces `base`.
/// - For all other cases (including type mismatches), `overlay` wins.
///
/// Returns the merged result without mutating either input.
pub fn throttle_function(base: &Value, overlay: &Value) -> Value {
    match (base, overlay) {
        (Value::Object(base_map), Value::Object(overlay_map)) => {
            let mut merged = base_map.clone();
            for (key, overlay_val) in overlay_map {
                match merged.get(key) {
                    Some(base_val) => {
                        merged.insert(key.clone(), throttle_function(base_val, overlay_val));
                    }
                    None => {
                        merged.insert(key.clone(), overlay_val.clone());
                    }
                }
            }
            Value::Object(merged)
        }
        _ => overlay.clone(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    // ── Basic merging ────────────────────────────────────────────────────

    #[test]
    fn flat_objects_merge_keys() {
        let base = json!({"a": 1, "b": 2});
        let overlay = json!({"b": 3, "c": 4});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, json!({"a": 1, "b": 3, "c": 4}));
    }

    #[test]
    fn overlay_completely_replaces_non_object_base() {
        let base = json!(42);
        let overlay = json!("hello");
        assert_eq!(throttle_function(&base, &overlay), json!("hello"));
    }

    #[test]
    fn base_object_overlay_scalar() {
        let base = json!({"a": 1});
        let overlay = json!(99);
        assert_eq!(throttle_function(&base, &overlay), json!(99));
    }

    #[test]
    fn base_scalar_overlay_object() {
        let base = json!(99);
        let overlay = json!({"a": 1});
        assert_eq!(throttle_function(&base, &overlay), json!({"a": 1}));
    }

    // ── Nested objects ───────────────────────────────────────────────────

    #[test]
    fn nested_objects_merged_recursively() {
        let base = json!({"db": {"host": "localhost", "port": 5432}});
        let overlay = json!({"db": {"port": 3306, "name": "mydb"}});
        let result = throttle_function(&base, &overlay);
        assert_eq!(
            result,
            json!({"db": {"host": "localhost", "port": 3306, "name": "mydb"}})
        );
    }

    #[test]
    fn deeply_nested_merge() {
        let base = json!({"a": {"b": {"c": {"d": 1, "e": 2}}}});
        let overlay = json!({"a": {"b": {"c": {"e": 99, "f": 3}}}});
        let result = throttle_function(&base, &overlay);
        assert_eq!(
            result,
            json!({"a": {"b": {"c": {"d": 1, "e": 99, "f": 3}}}})
        );
    }

    #[test]
    fn three_level_partial_overlay() {
        let base = json!({
            "level1": {
                "level2": {
                    "keep": "original",
                    "replace": "old"
                }
            }
        });
        let overlay = json!({
            "level1": {
                "level2": {
                    "replace": "new"
                }
            }
        });
        let result = throttle_function(&base, &overlay);
        assert_eq!(
            result,
            json!({
                "level1": {
                    "level2": {
                        "keep": "original",
                        "replace": "new"
                    }
                }
            })
        );
    }

    // ── Arrays ───────────────────────────────────────────────────────────

    #[test]
    fn arrays_are_replaced_not_merged() {
        let base = json!({"tags": [1, 2, 3]});
        let overlay = json!({"tags": [4, 5]});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, json!({"tags": [4, 5]}));
    }

    #[test]
    fn array_overlay_replaces_array_base() {
        let base = json!([1, 2, 3]);
        let overlay = json!([4, 5]);
        assert_eq!(throttle_function(&base, &overlay), json!([4, 5]));
    }

    #[test]
    fn object_overlay_replaces_array_base() {
        let base = json!([1, 2]);
        let overlay = json!({"key": "value"});
        assert_eq!(throttle_function(&base, &overlay), json!({"key": "value"}));
    }

    // ── Null handling ────────────────────────────────────────────────────

    #[test]
    fn null_overlay_replaces_value() {
        let base = json!({"key": "value"});
        let overlay = json!({"key": null});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, json!({"key": null}));
    }

    #[test]
    fn value_overlay_replaces_null() {
        let base = json!({"key": null});
        let overlay = json!({"key": "value"});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, json!({"key": "value"}));
    }

    // ── Empty objects ────────────────────────────────────────────────────

    #[test]
    fn empty_overlay_returns_base_clone() {
        let base = json!({"a": 1, "b": {"c": 2}});
        let overlay = json!({});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, base);
    }

    #[test]
    fn empty_base_returns_overlay_clone() {
        let base = json!({});
        let overlay = json!({"a": 1, "b": {"c": 2}});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, overlay);
    }

    #[test]
    fn both_empty_objects() {
        let base = json!({});
        let overlay = json!({});
        assert_eq!(throttle_function(&base, &overlay), json!({}));
    }

    // ── Type mismatches ──────────────────────────────────────────────────

    #[test]
    fn scalar_type_change() {
        let base = json!({"key": 42});
        let overlay = json!({"key": "string"});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, json!({"key": "string"}));
    }

    #[test]
    fn object_to_array_type_change() {
        let base = json!({"key": {"nested": true}});
        let overlay = json!({"key": [1, 2, 3]});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, json!({"key": [1, 2, 3]}));
    }

    #[test]
    fn array_to_object_type_change() {
        let base = json!({"key": [1, 2, 3]});
        let overlay = json!({"key": {"nested": true}});
        let result = throttle_function(&base, &overlay);
        assert_eq!(result, json!({"key": {"nested": true}}));
    }

    // ── Mixed value types in same object ─────────────────────────────────

    #[test]
    fn mixed_value_types() {
        let base = json!({
            "str": "hello",
            "num": 42,
            "bool": true,
            "null": null,
            "arr": [1, 2],
            "obj": {"inner": "value"}
        });
        let overlay = json!({
            "num": 100,
            "obj": {"inner": "updated", "new_key": true}
        });
        let result = throttle_function(&base, &overlay);
        assert_eq!(
            result,
            json!({
                "str": "hello",
                "num": 100,
                "bool": true,
                "null": null,
                "arr": [1, 2],
                "obj": {"inner": "updated", "new_key": true}
            })
        );
    }

    // ── Overlay adds new nested keys ─────────────────────────────────────

    #[test]
    fn overlay_adds_new_nested_branch() {
        let base = json!({"existing": 1});
        let overlay = json!({"new_branch": {"deep": {"deeper": 42}}});
        let result = throttle_function(&base, &overlay);
        assert_eq!(
            result,
            json!({"existing": 1, "new_branch": {"deep": {"deeper": 42}}})
        );
    }

    // ── Both inputs are arrays ───────────────────────────────────────────

    #[test]
    fn both_arrays_overlay_wins() {
        let base = json!([1, 2, 3]);
        let overlay = json!(["a", "b"]);
        assert_eq!(throttle_function(&base, &overlay), json!(["a", "b"]));
    }

    // ── Config-style merging scenario ────────────────────────────────────

    #[test]
    fn config_merge_scenario() {
        let defaults = json!({
            "server": {
                "host": "0.0.0.0",
                "port": 8080,
                "tls": false
            },
            "database": {
                "host": "localhost",
                "port": 5432,
                "pool_size": 10
            },
            "logging": {
                "level": "info",
                "format": "json"
            }
        });
        let user_config = json!({
            "server": {
                "port": 443,
                "tls": true
            },
            "database": {
                "host": "db.example.com",
                "pool_size": 25
            }
        });
        let result = throttle_function(&defaults, &user_config);
        assert_eq!(
            result,
            json!({
                "server": {
                    "host": "0.0.0.0",
                    "port": 443,
                    "tls": true
                },
                "database": {
                    "host": "db.example.com",
                    "port": 5432,
                    "pool_size": 25
                },
                "logging": {
                    "level": "info",
                    "format": "json"
                }
            })
        );
    }

    // ── Deeply nested with multiple branches ─────────────────────────────

    #[test]
    fn multiple_branches_at_same_level() {
        let base = json!({
            "a": {"x": 1},
            "b": {"y": 2},
            "c": {"z": 3}
        });
        let overlay = json!({
            "a": {"x": 10, "new": 11},
            "c": {"z": 30}
        });
        let result = throttle_function(&base, &overlay);
        assert_eq!(
            result,
            json!({
                "a": {"x": 10, "new": 11},
                "b": {"y": 2},
                "c": {"z": 30}
            })
        );
    }

    // ── Inputs are not mutated ───────────────────────────────────────────

    #[test]
    fn base_is_not_mutated() {
        let base = json!({"a": {"b": 1}});
        let overlay = json!({"a": {"c": 2}});
        let _result = throttle_function(&base, &overlay);
        assert_eq!(base, json!({"a": {"b": 1}}));
    }

    #[test]
    fn overlay_is_not_mutated() {
        let base = json!({"a": {"b": 1}});
        let overlay = json!({"a": {"c": 2}});
        let _result = throttle_function(&base, &overlay);
        assert_eq!(overlay, json!({"a": {"c": 2}}));
    }
}
